code.java:
public long flippingBits(long n) {
    long result = 0;
    for (int i = 0; i < 32; i++) {
        long bit = (n >> i) & 1;     // read bit i
        if (bit == 0) {
            result |= (1L << i);     // 0 flips to 1
        }
    }
    return result;
}

code.python:
def flippingBits(n: int) -> int:
    result = 0
    for i in range(32):
        bit = (n >> i) & 1           # read bit i
        if bit == 0:
            result |= (1 << i)       # 0 flips to 1
    return result

